public class Solution {
    // Leitor r e escritor w no mesmo sentido. O(n), O(1).
    static int removerDuplicatas(int[] nums) {
        if (nums.length == 0) return 0;
        int w = 1;
        for (int r = 1; r < nums.length; r++) {
            if (nums[r] != nums[w - 1]) nums[w++] = nums[r];
        }
        return w;
    }
}

