import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplo() {
        int[] a = {1, 1, 2, 3, 3, 3, 4};
        int k = Solution.removerDuplicatas(a);
        assertEquals(4, k);
        assertArrayEquals(new int[]{1, 2, 3, 4}, java.util.Arrays.copyOf(a, k));
    }

    @Test void bordas() {
        assertEquals(0, Solution.removerDuplicatas(new int[]{}));
        int[] um = {5};
        assertEquals(1, Solution.removerDuplicatas(um));
        int[] iguais = {2, 2, 2, 2};
        assertEquals(1, Solution.removerDuplicatas(iguais));
        assertEquals(2, iguais[0]);
    }

    @Test void semDuplicatas() {
        int[] a = {-3, 0, 4, 9};
        assertEquals(4, Solution.removerDuplicatas(a));
        assertArrayEquals(new int[]{-3, 0, 4, 9}, a);
    }
}

