import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void exemplo() {
        assertEquals(List.of(List.of(-1, -1, 2), List.of(-1, 0, 1)), Solution.threeSum(new int[]{-1, 0, 1, 2, -1, -4}));
    }

    @Test void zerosRepetidos() {
        assertEquals(List.of(List.of(0, 0, 0)), Solution.threeSum(new int[]{0, 0, 0, 0, 0}));
    }

    @Test void nenhuma() {
        assertEquals(List.of(), Solution.threeSum(new int[]{1, 2, 3}));
        assertEquals(List.of(), Solution.threeSum(new int[]{}));
    }

    @Test void muitasDuplicatas() {
        assertEquals(List.of(List.of(-2, 0, 2), List.of(-2, 1, 1), List.of(-1, -1, 2), List.of(-1, 0, 1)),
            Solution.threeSum(new int[]{-2, -2, -1, -1, 0, 0, 1, 1, 2, 2}));
    }

    @Test void grande() {
        int[] a = new int[3000];
        for (int i = 0; i < a.length; i++) a[i] = (i % 61) - 30;
        assertEquals(Solution.threeSum(a).size(), new HashSet<>(Solution.threeSum(a)).size());
    }
}
